import React from "react";
import Topnav from "@/components/Topnav";
import Navbar2 from "@/components/Navbar2";
import Footer2 from "@/components/Footer2";
import BottomFooter from "@/components/BottomFooter";

// Dynamically import ServicesTabs with the global preloader
import dynamic from "next/dynamic";

// Import the GlobalPreloader component
import GlobalPreloader from "@/components/GlobalPreloader";

// Dynamically import ServicesTabs with loading state
const ServicesTabs = dynamic(() => import("@/components/ServicesTabs"), {
  ssr: false, // Disable SSR for this component
  loading: () => <GlobalPreloader /> // Show GlobalPreloader while loading
});

const Services = () => {
  return (
    <div>
      <Topnav />
      <Navbar2 />
      {/* Render ServicesTabs dynamically */}
      <ServicesTabs />
      <Footer2 />
      <BottomFooter />
    </div>
  );
};

export default Services;
